const payload = $('Execute Workflow Trigger').item.json || {};
const chatId = String(payload.chatId || payload.message?.chat?.id || '').trim();
const factText = String(payload.fact_text || payload.factText || '').trim();
const category = String(payload.category || 'general').trim() || 'general';
const sourceText = String(payload.rawText || payload.text || factText || '').trim();
const tags = Array.isArray(payload.tags)
  ? payload.tags.map((tag) => String(tag || '').trim()).filter(Boolean)
  : String(payload.tags || '')
      .split(',')
      .map((tag) => tag.trim())
      .filter(Boolean);
const confidence = Math.max(0, Math.min(1, Number(payload.confidence || 0.85) || 0.85));

const escapeSql = (value = '') => String(value || '').replace(/'/g, "''");
const normalize = (value = '') => String(value || '')
  .toLowerCase()
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .replace(/đ/g, 'd')
  .trim();
const hashHex = (input) => {
  let h1 = 0xdeadbeef ^ input.length;
  let h2 = 0x41c6ce57 ^ input.length;
  for (let index = 0; index < input.length; index += 1) {
    const codePoint = input.charCodeAt(index);
    h1 = Math.imul(h1 ^ codePoint, 2654435761);
    h2 = Math.imul(h2 ^ codePoint, 1597334677);
  }
  h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909);
  h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909);
  return `${(h2 >>> 0).toString(16).padStart(8, '0')}${(h1 >>> 0).toString(16).padStart(8, '0')}`;
};

if (!chatId) {
  throw new Error('Missing chatId for memory_save_fact');
}

if (!factText) {
  return [{
    json: {
      chatId,
      skip: true,
      responseText: 'MEMORY_SAVE_FACT_SKIPPED\nreason: empty fact'
    }
  }];
}

const fingerprint = hashHex(`${chatId}|${normalize(category)}|${normalize(factText)}`);
const tagsSql = `ARRAY[${tags.map((tag) => `'${escapeSql(tag)}'`).join(', ')}]::text[]`;
const upsertSql = `INSERT INTO mia_facts (chat_id, fingerprint, fact_text, category, tags, source_text, confidence, is_active, created_at, updated_at) VALUES ('${escapeSql(chatId)}', '${fingerprint}', '${escapeSql(factText)}', '${escapeSql(category)}', ${tags.length ? tagsSql : 'ARRAY[]::text[]'}, '${escapeSql(sourceText)}', ${confidence.toFixed(2)}, true, now(), now()) ON CONFLICT (fingerprint) DO UPDATE SET fact_text = EXCLUDED.fact_text, category = EXCLUDED.category, tags = EXCLUDED.tags, source_text = EXCLUDED.source_text, confidence = EXCLUDED.confidence, is_active = true, updated_at = now() RETURNING chat_id, fact_text, category, tags, confidence, updated_at;`;

return [{
  json: {
    chatId,
    skip: false,
    factText,
    category,
    tags,
    confidence,
    upsertSql
  }
}];

const source = $('Prepare Fact Input').item.json || {};
if (source.skip) {
  return [{ json: { text: source.responseText, chatId: source.chatId || '' } }];
}
const row = $json || {};
const tags = Array.isArray(row.tags) ? row.tags.filter(Boolean).join(', ') : '';
const parts = [
  'MEMORY_SAVE_FACT_OK',
  `category: ${row.category || source.category || 'general'}`,
  `fact: ${row.fact_text || source.factText || ''}`,
  `confidence: ${row.confidence || source.confidence || 0.85}`
];
if (tags) parts.push(`tags: ${tags}`);
return [{ json: { text: parts.join('\n'), chatId: row.chat_id || source.chatId || '' } }];
